import fs from 'fs';
import path from 'path';
import sharp from 'sharp';
import manifest from '@/app/manifest';
import { BLOG_LOGO_URL } from '@/lib/blog/seo';
import { BRAND_ASSETS, BRAND_ICONS, logoColors } from '@/lib/brand';

/**
 * Guards for the logo files served as-is from public/ (no next/image).
 * They are generated by `npm run brand:build`; these checks read the bytes, so
 * a declared type or size can never drift from what is actually shipped (the
 * old manifest once declared a 1024 px JPEG as `image/png`, `sizes: any`).
 */

const publicDir = path.resolve(__dirname, '..', 'public');
const file = (url: string) => path.join(publicDir, ...url.split('/').filter(Boolean));

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function pngSize(buf: Buffer): { width: number; height: number } | null {
    if (!buf.subarray(0, 8).equals(PNG_SIGNATURE)) return null;
    // IHDR is the first chunk: width/height are big-endian uint32 at offsets 16/20.
    return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
}

function icoEntries(buf: Buffer) {
    expect(buf.readUInt16LE(0)).toBe(0);
    expect(buf.readUInt16LE(2)).toBe(1);
    return Array.from({ length: buf.readUInt16LE(4) }, (_, i) => {
        const at = 6 + 16 * i;
        const png = buf.subarray(buf.readUInt32LE(at + 12), buf.readUInt32LE(at + 12) + buf.readUInt32LE(at + 8));
        return { size: buf.readUInt8(at) || 256, png };
    });
}

describe('brand files', () => {
    it.each(Object.entries(BRAND_ASSETS))('%s exists in public/', (_key, asset) => {
        expect(fs.existsSync(file(asset.url))).toBe(true);
    });

    it.each(
        Object.entries(BRAND_ASSETS).filter(([, a]) => a.type === 'image/png') as [string, { url: string; width: number; height: number }][]
    )('%s is a real PNG of its declared size', (_key, asset) => {
        expect(pngSize(fs.readFileSync(file(asset.url)))).toEqual({ width: asset.width, height: asset.height });
    });

    it('favicon.ico holds 16, 32 and 48 px PNGs', () => {
        const entries = icoEntries(fs.readFileSync(file(BRAND_ASSETS.favicon.url)));
        expect(entries.map((e) => e.size)).toEqual([16, 32, 48]);
        for (const e of entries) expect(pngSize(e.png)).toEqual({ width: e.size, height: e.size });
    });

    it('icon.svg is square and switches tone in dark mode', () => {
        const svg = fs.readFileSync(file(BRAND_ASSETS.iconSvg.url), 'utf8');
        const [, , w, h] = /viewBox="([^"]+)"/.exec(svg)![1].split(/\s+/).map(Number);
        expect(w).toBeCloseTo(h, 3);
        expect(svg).toContain('@media (prefers-color-scheme:dark)');
    });

    it('the maskable icon keeps the art inside the 80 % safe circle', async () => {
        const { url, width } = BRAND_ASSETS.maskable512;
        const { data, info } = await sharp(file(url)).raw().toBuffer({ resolveWithObject: true });
        const plate = logoColors.background.match(/[0-9a-f]{2}/g)!.map((h) => parseInt(h, 16));
        const r = (0.8 * width) / 2;
        let outside = 0;
        for (let y = 0; y < info.height; y++) {
            for (let x = 0; x < info.width; x++) {
                if (Math.hypot(x + 0.5 - width / 2, y + 0.5 - width / 2) <= r) continue;
                const i = (y * info.width + x) * info.channels;
                if ([0, 1, 2].some((c) => Math.abs(data[i + c] - plate[c]) > 2)) outside++;
            }
        }
        expect(outside).toBe(0);
    });

    it('the default link preview is 1200x630 (Open Graph 1.91:1)', () => {
        expect(pngSize(fs.readFileSync(file(BRAND_ASSETS.ogDefault.url)))).toEqual({ width: 1200, height: 630 });
    });
});

describe('web app manifest', () => {
    const icons = manifest().icons ?? [];

    it('provides the 192px and 512px icons required for installability', () => {
        expect(icons.filter((i) => i.purpose === 'any').map((i) => i.sizes)).toEqual(
            expect.arrayContaining(['192x192', '512x512'])
        );
    });

    it('provides a maskable icon so Android does not shrink the logo into a white disc', () => {
        expect(icons.filter((i) => i.purpose === 'maskable').map((i) => i.sizes)).toContain('512x512');
    });

    it.each(icons.map((i) => [i.src, i] as const))('%s is a real PNG of its declared size', (src, icon) => {
        expect(icon.type).toBe('image/png');
        const size = pngSize(fs.readFileSync(file(src)));
        expect(size && `${size.width}x${size.height}`).toBe(icon.sizes);
    });
});

describe('<head> icons', () => {
    it('declares the ICO as 32x32 (not `any`, which makes Chrome prefer it over the SVG)', () => {
        const icon = BRAND_ICONS.icon as { url: string; sizes?: string; type?: string }[];
        expect(icon).toEqual([
            { url: '/favicon.ico', sizes: '32x32' },
            { url: '/brand/icon.svg', type: 'image/svg+xml' },
        ]);
    });
});

describe('public/ hygiene', () => {
    it('ships no file whose PNG extension hides other content', () => {
        const pngs: string[] = [];
        const walk = (dir: string) => {
            for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
                const full = path.join(dir, entry.name);
                if (entry.isDirectory()) walk(full);
                else if (entry.name.toLowerCase().endsWith('.png')) pngs.push(full);
            }
        };
        walk(publicDir);
        const mislabelled = pngs.filter((f) => pngSize(fs.readFileSync(f)) === null).map((f) => path.relative(publicDir, f));
        expect(mislabelled).toEqual([]);
    });
});

describe('structured-data logo', () => {
    it('points to a real PNG of at least 112px shipped in public/', () => {
        // Google requires >= 112x112 for Organization/publisher logos.
        const size = pngSize(fs.readFileSync(file(new URL(BLOG_LOGO_URL).pathname)));
        expect(size).not.toBeNull();
        expect(size!.width).toBeGreaterThanOrEqual(112);
        expect(size!.height).toBeGreaterThanOrEqual(112);
    });
});
